std::vector<int> V1 = {1, 3, 5};   // Required: Sorted Input
std::vector<int> V2 = {3, 4, 5};   // Required: Sorted Input
std::vector<int> Vout;

// Complexity: O(N1 + N2) comparisons (linear scan)
// Uses two input iterators advanced simultaneously
auto end_it = std::set_intersection(
    V1.begin(), V1.end(),
    V2.begin(), V2.end(),
    std::back_inserter(Vout), // Output Iterator (e.g., stream, inserter)
    std::less<int>()         // Optional Binary Predicate
);

// Vout == {3, 5}
// Returns iterator pointing past last copied element
// Constraint: Input ranges must be ordered consistently with Predicate
